using System.Collections.Generic;
using VMLAssembler;

namespace VMLTranslators
{
    /// <summary>
    /// ARM Cortex-M 转译器
    /// </summary>
    public class TranslatorARMCM : Translator32bit
    {
        public override string ARCH_NAME => "ARM-CM";

        protected override string[] ContextRegNames() => new[] { "r0", "r1", "r2", "r3", "r4", "r5", "r6", "r7", "lr" };
        protected override string NativeInt(int vector) => $"svc #{vector}";
        protected override string NativeIret() => "";  // pop {..., pc} 已处理返回
        protected override string NativeCli() => "cpsid i";
        protected override string NativeSti() => "cpsie i";

        protected override void EmitSaveContext()
            => Emit("        push {r0, r1, r2, r3, r4, r5, r6, r7, lr}");

        protected override void EmitRestoreContext()
            => Emit("        pop {r0, r1, r2, r3, r4, r5, r6, r7, pc}");

        private readonly Dictionary<int, string> REGISTER_MAP = new Dictionary<int, string>
        {
            { 0, "R0" },
            { 1, "R1" },
            { 2, "R2" },
            { 3, "R3" },
            { 4, "R4" },
            { 5, "R5" },
            { 6, "R6" },
            { 7, "R7" }
        };

        public TranslatorARMCM(VmlProgram vmlProgram) : base(vmlProgram) { }

        protected override void EmitHeader()
        {
            Emit("@ ARM Cortex-M Assembly - Translated from VML");
            Emit("@ Generated by VML Translator");
            Emit("@ Target: STM32F103C8T6 (Cortex-M3)");
            Emit("");
            Emit("        .syntax unified");
            Emit("        .thumb");
            Emit("");
            if (!SkipHeader)
            {
                Emit("@ ======== Vector Table ========");
                Emit("        .section .vectors,\"ax\"");
                Emit("        .align 2");
                Emit("        .global _vectors");
                Emit("_vectors:");
            }
            if (!SkipHeader)
            {
                Emit($"        .word 0x{StackTop:X8}             @ 0: SP (RAM: 0x{RamBase:X8}+{RamSize/1024}KB)");
                Emit("        .word Reset_Handler          @ 1: Reset_Handler");
                Emit("        .word Default_Handler        @ 2: NMI");
                Emit("        .word Default_Handler        @ 3: HardFault");
                Emit("        .word Default_Handler        @ 4: MemManage");
                Emit("        .word Default_Handler        @ 5: BusFault");
                Emit("        .word Default_Handler        @ 6: UsageFault");
                Emit("        .word 0                       @ 7: Reserved");
                Emit("        .word 0                       @ 8: Reserved");
                Emit("        .word 0                       @ 9: Reserved");
                Emit("        .word 0                       @ 10: Reserved");
                Emit("        .word Default_Handler        @ 11: SVCall");
                Emit("        .word Default_Handler        @ 12: DebugMon");
                Emit("        .word 0                       @ 13: Reserved");
                Emit("        .word Default_Handler        @ 14: PendSV");
                Emit("        .word Default_Handler        @ 15: SysTick");
                Emit("");
                Emit("@ ======== Stack definition ========");
                Emit("        .set __stack_top, 0x20010000");
                Emit("");
                Emit("@ ======== Exception Handlers ========");
                Emit("        .section .text");
                Emit("        .align 2");
                Emit("        .thumb_func");
                Emit("        .global Default_Handler");
                Emit("Default_Handler:");
                Emit("        b .                         @ infinite loop");
                Emit("");
                Emit("@ ======== Reset Handler ========");
                Emit("        .thumb_func");
                Emit("        .global Reset_Handler");
                Emit("Reset_Handler:");
                Emit($"        ldr r0, =0x{StackTop:X8}");
                Emit("        mov sp, r0");
                Emit("        bl main");
                Emit("        b .");
            }
            Emit("");
            Emit("@ ======== VML Program Code ========");
            Emit("        .section .text.vml");
            Emit("        .align 2");
        }

        protected override void EmitDataSection()
        {
            if (VmlProgram.DataSection.Count > 0)
            {
                Emit("");
                Emit("        .data");
                Emit("        .align 2");
                foreach (var kvp in VmlProgram.DataSection)
                {
                    string name = kvp.Key;
                    object value = kvp.Value;

                    if (value is DataString ds)
                    {
                        string escaped = EscapeString(ds.Value);
                        Emit($"{name}:");
                        if (ds.Width == StringWidth.Wide)
                            Emit($"        .2byte \"{escaped}\"");  // UTF-16
                        else if (ds.Width == StringWidth.Unicode)
                            Emit($"        .4byte \"{escaped}\"");  // UTF-32
                        else
                            Emit($"        .asciz \"{escaped}\"");
                    }
                    else if (value is string strValue)
                    {
                        string escaped = EscapeString(strValue);
                        Emit($"{name}:");
                        Emit($"        .asciz \"{escaped}\"");
                    }
                    else if (value is System.Collections.IList listValue)
                    {
                        string vals = string.Join(", ", listValue);
                        Emit($"{name}: .byte {vals}");
                    }
                    else if (int.TryParse(value.ToString(), out int intValue))
                    {
                        Emit($"{name}: .word {intValue}");
                    }
                }
            }
        }

        protected override void EmitCode()
        {
            Emit("");
            Emit("        .text");
            Emit("        .align 2");
            // CALL链追踪: 只翻译可达代码
            string entryName = VmlProgram.EntryPoint ?? "main";
            var reachableAddrs = new HashSet<int>();
            var queue = new Queue<int>();

            // Start from entry point
            if (VmlProgram.Labels.TryGetValue(entryName, out int entryAddr))
            {
                queue.Enqueue(entryAddr);
                reachableAddrs.Add(entryAddr);
            }

            while (queue.Count > 0)
            {
                int addr = queue.Dequeue();
                for (int j = addr; j < VmlProgram.Instructions.Count; j++)
                {
                    if (j > addr && reachableAddrs.Contains(j)) break; // 遇到另一个函数起点则停止
                    reachableAddrs.Add(j);
                    var inst = VmlProgram.Instructions[j];
                    if (inst.Opcode == OpCode.CALL && inst.Operands.Count > 0)
                    {
                        string callee = inst.Operands[0].Value?.ToString() ?? "";
                        if (!string.IsNullOrEmpty(callee) && VmlProgram.Labels.TryGetValue(callee, out int calleeAddr))
                        {
                            if (!reachableAddrs.Contains(calleeAddr))
                            {
                                reachableAddrs.Add(calleeAddr);
                                queue.Enqueue(calleeAddr);
                            }
                        }
                    }
                    if (inst.Opcode == OpCode.RET || inst.Opcode == OpCode.HALT) break;
                }
            }

            // Build labelAtAddr for reachable code
            var labelAtAddr = new Dictionary<int, string>();
            foreach (var kv in VmlProgram.Labels)
                if (reachableAddrs.Contains(kv.Value))
                    labelAtAddr[kv.Value] = kv.Key;

            // Emit reachable instructions in order
            for (int i = 0; i < VmlProgram.Instructions.Count; i++)
            {
                if (!reachableAddrs.Contains(i)) continue;
                var instr = VmlProgram.Instructions[i];
                if (labelAtAddr.TryGetValue(i, out var lbl))
                    Emit($"{lbl}:");
                if (!string.IsNullOrEmpty(instr.Label) && !labelAtAddr.ContainsKey(i))
                    Emit($"{instr.Label}:");
                NormalizeAndTranslate(instr);
            }
        }

        /// <summary>ARM-CM 使用 bl 而非 call</summary>
        protected override void EmitCall(Instruction instr)
            => Emit($"        bl __{instr.Opcode.ToString().ToLower()}");

        /// <summary>ARM-CM 内联实现 64-bit 位运算，不委托给基类软件库</summary>
        protected override bool TryTranslateCommonOpcode(Instruction instr)
        {
            // ANDL/ORL/XORL/NOTL 由 TranslateInstruction 内联处理
            // SHLL/SHRL 由 TranslateInstruction 用 bl __shll/__shrl 处理
            if (instr.Opcode is OpCode.ANDL or OpCode.ORL or OpCode.XORL or OpCode.NOTL
                or OpCode.SHLL or OpCode.SHRL)
                return false;
            return base.TryTranslateCommonOpcode(instr);
        }

        protected override void TranslateInstruction(Instruction instr)
        {
            // NormalizeBinaryOp handled by BaseTranslator.NormalizeAndTranslate
            switch (instr.Opcode)
            {
                                                case OpCode.ADD:
                    TranslateAdd(instr);
                    break;
                case OpCode.SUB:
                    TranslateSub(instr);
                    break;
                case OpCode.MUL:
                    TranslateMul(instr);
                    break;
                case OpCode.MOVE:
                    TranslateMove(instr);
                    break;
                case OpCode.CMP:
                    TranslateCmp(instr);
                    break;
                case OpCode.JMP:
                    Emit($"        b {instr.Operands[0].Value}");
                    break;
                case OpCode.JZ:
                    Emit($"        beq {instr.Operands[0].Value}");
                    break;
                case OpCode.JNZ:
                    Emit($"        bne {instr.Operands[0].Value}");
                    break;
                case OpCode.JE:
                    Emit($"        beq {instr.Operands[0].Value}");
                    break;
                case OpCode.JNE:
                    Emit($"        bne {instr.Operands[0].Value}");
                    break;
                case OpCode.JL:
                    Emit($"        blt {instr.Operands[0].Value}");
                    break;
                case OpCode.JLE:
                    Emit($"        ble {instr.Operands[0].Value}");
                    break;
                case OpCode.JG:
                    Emit($"        bgt {instr.Operands[0].Value}");
                    break;
                case OpCode.JGE:
                    Emit($"        bge {instr.Operands[0].Value}");
                    break;
                case OpCode.HALT:
                    Emit("        wfi");
                    break;
                case OpCode.NOP:
                    Emit("        nop");
                    break;
                // CLI/STI/INT/IRET handled by BaseTranslator.TryTranslateCommonOpcode
                case OpCode.THROW:
                    Emit("        movs r0, " + GetOperandValue(instr.Operands[0]));
                    Emit("        svc #0");
                    break;
                case OpCode.CATCH:
                    Emit($"        ldr r0, ={instr.Operands[0].Value}");
                    Emit("        str r0, [r1, #0]");
                    break;
                case OpCode.ENDCATCH:
                    Emit("        movs r0, #0");
                    Emit("        str r0, [r1, #0]");
                    break;

                // 浮点运算指令 (软浮点库调用)
                case OpCode.FADD:
                    Emit("        @ FADD - 软浮点实现");
                    Emit("        bl __addsf3");
                    break;
                case OpCode.FSUB:
                    Emit("        @ FSUB - 软浮点实现");
                    Emit("        bl __subsf3");
                    break;
                case OpCode.FMUL:
                    Emit("        @ FMUL - 软浮点实现");
                    Emit("        bl __mulsf3");
                    break;
                case OpCode.FDIV:
                    Emit("        @ FDIV - 软浮点实现");
                    Emit("        bl __divsf3");
                    break;
                case OpCode.FNEG:
                    Emit("        @ FNEG - 符号位取反");
                    Emit("        eor r0, r0, #0x80000000");
                    break;
                case OpCode.FCMP:
                    Emit("        @ FCMP - 软浮点比较");
                    Emit("        bl __lesf2");
                    break;

                // 浮点类型转换
                case OpCode.I2F:
                    Emit("        bl __floatsisf");
                    break;
                case OpCode.F2I:
                    Emit("        bl __fixsfsi");
                    break;
                case OpCode.F2D:
                    Emit("        bl __extendsfdf2");
                    break;
                case OpCode.D2F:
                    Emit("        bl __truncdfsf2");
                    break;

                // 浮点数据传输
                case OpCode.MOVEF:
                    // MOVEF Rd, Rs — register-to-register float move (v1.66.31 fix)
                    Emit($"        mov {MapRegister(SafeToInt(instr.Operands[0]))}, {MapRegister(SafeToInt(instr.Operands[1]))}");
                    break;
                case OpCode.FPUSH:
                    Emit("        push {r0}");
                    break;
                case OpCode.FPOP:
                    Emit("        pop {r0}");
                    break;

                // --- 缺失的指令补全 ---

                // 整数除法 (Cortex-M0 无硬件除法，用软件模拟)
                case OpCode.DIV:
                    {
                        string dstReg = MapRegister((int)instr.Operands[0].Value);
                        string src1Reg = GetOperandValue(instr.Operands[1]);
                        string src2Reg = GetOperandValue(instr.Operands[2]);
                        Emit($"        @ DIV R{dstReg}, R{src1Reg}, R{src2Reg} (软件实现)");
                        Emit($"        movs R4, {src1Reg}");   // 被除数
                        Emit($"        movs R5, {src2Reg}");   // 除数
                        Emit($"        bl __divsi3");          // GCC 内置除法子程序
                        Emit($"        movs {dstReg}, R0");    // 结果放目标寄存器
                    }
                    break;

                // 模运算 (DIV 后取余)
                case OpCode.MOD:
                    {
                        string dstReg = MapRegister((int)instr.Operands[0].Value);
                        string src1Reg = GetOperandValue(instr.Operands[1]);
                        string src2Reg = GetOperandValue(instr.Operands[2]);
                        Emit($"        @ MOD R{dstReg}, R{src1Reg}, R{src2Reg} (软件实现)");
                        Emit($"        movs R4, {src1Reg}");
                        Emit($"        movs R5, {src2Reg}");
                        Emit($"        bl __modsi3");          // GCC 内置取模子程序
                        Emit($"        movs {dstReg}, R0");
                    }
                    break;

                // 位运算指令 (Cortex-M3 Thumb-2 三操作数形式)
                case OpCode.AND:
                    {
                        string dstReg = MapRegister((int)instr.Operands[0].Value);
                        string src1Reg = GetOperandValue(instr.Operands[1]);
                        if (instr.Operands[2].Type == OperandType.IMMEDIATE)
                        {
                            Emit($"        movs R6, #{instr.Operands[2].Value}");
                            Emit($"        ands {dstReg}, {src1Reg}, R6");
                        }
                        else
                        {
                            string src2Reg = GetOperandValue(instr.Operands[2]);
                            Emit($"        ands {dstReg}, {src1Reg}, {src2Reg}");
                        }
                    }
                    break;
                case OpCode.OR:
                    {
                        string dstReg = MapRegister((int)instr.Operands[0].Value);
                        string src1Reg = GetOperandValue(instr.Operands[1]);
                        if (instr.Operands[2].Type == OperandType.IMMEDIATE)
                        {
                            Emit($"        movs R6, #{instr.Operands[2].Value}");
                            Emit($"        orrs {dstReg}, {src1Reg}, R6");
                        }
                        else
                        {
                            string src2Reg = GetOperandValue(instr.Operands[2]);
                            Emit($"        orrs {dstReg}, {src1Reg}, {src2Reg}");
                        }
                    }
                    break;
                case OpCode.XOR:
                    {
                        string dstReg = MapRegister((int)instr.Operands[0].Value);
                        string src1Reg = GetOperandValue(instr.Operands[1]);
                        if (instr.Operands[2].Type == OperandType.IMMEDIATE)
                        {
                            Emit($"        movs R6, #{instr.Operands[2].Value}");
                            Emit($"        eors {dstReg}, {src1Reg}, R6");
                        }
                        else
                        {
                            string src2Reg = GetOperandValue(instr.Operands[2]);
                            Emit($"        eors {dstReg}, {src1Reg}, {src2Reg}");
                        }
                    }
                    break;
                case OpCode.NOT:
                    Emit($"        movs R4, {GetOperandValue(instr.Operands[0])}");
                    Emit($"        mvns R4, R4");
                    Emit($"        movs {MapRegister((int)instr.Operands[0].Value)}, R4");
                    break;

                // 移位指令 (Cortex-M0: LSL/LSR 立即数支持，变量移位用 LSL/LSR Rn, Rm)
                case OpCode.ZERO:
                    Emit($"        movs {MapRegister((int)instr.Operands[0].Value)}, #0");
                    break;
                // OpCode.CHIPASM handled by BaseTranslator.TryTranslateCommonOpcode
                case OpCode.SHL:
                case OpCode.SHLV:
                    if (instr.Operands[2].Type == OperandType.IMMEDIATE)
                    {
                        Emit($"        lsls {MapRegister((int)instr.Operands[0].Value)}, {GetOperandValue(instr.Operands[1])}, #{instr.Operands[2].Value}");
                    }
                    else
                    {
                        Emit($"        movs R4, {GetOperandValue(instr.Operands[1])}");
                        Emit($"        lsls R4, R4, {GetOperandValue(instr.Operands[2])}");
                        Emit($"        movs {MapRegister((int)instr.Operands[0].Value)}, R4");
                    }
                    break;
                case OpCode.SHR:
                case OpCode.SHRV:
                    if (instr.Operands[2].Type == OperandType.IMMEDIATE)
                    {
                        Emit($"        lsrs {MapRegister((int)instr.Operands[0].Value)}, {GetOperandValue(instr.Operands[1])}, #{instr.Operands[2].Value}");
                    }
                    else
                    {
                        Emit($"        movs R4, {GetOperandValue(instr.Operands[1])}");
                        Emit($"        lsrs R4, R4, {GetOperandValue(instr.Operands[2])}");
                        Emit($"        movs {MapRegister((int)instr.Operands[0].Value)}, R4");
                    }
                    break;

                // 单目算术指令
                case OpCode.INC:
                    Emit($"        adds {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[0])}, #1");
                    break;
                case OpCode.DEC:
                    Emit($"        subs {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[0])}, #1");
                    break;
                case OpCode.NEG:
                    Emit($"        rsbs {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[0])}, #0");
                    break;

                // TEST: 与运算设置标志位
                case OpCode.TEST:
                    if (instr.Operands[1].Type == OperandType.IMMEDIATE)
                    {
                        Emit($"        movs R4, {GetOperandValue(instr.Operands[0])}");
                        Emit($"        ands R4, R4, #{instr.Operands[1].Value}");
                    }
                    else
                    {
                        Emit($"        movs R4, {GetOperandValue(instr.Operands[0])}");
                        Emit($"        ands R4, R4, {GetOperandValue(instr.Operands[1])}");
                    }
                    break;

                // 栈操作 (Cortex-M3 PUSH/POP, R15=RA→LR)
                case OpCode.PUSH:
                    {
                        string reg = GetOperandValue(instr.Operands[0]);
                        if (reg == "R15") reg = "lr";
                        else if (reg == "R14") reg = "lr";
                        else if (reg == "R13") reg = "sp";
                        Emit($"        push {{{reg}}}");
                    }
                    break;
                case OpCode.POP:
                    {
                        string reg = GetOperandValue(instr.Operands[0]);
                        if (reg == "R15") reg = "pc";
                        else if (reg == "R14") reg = "lr";
                        else if (reg == "R13") reg = "sp";
                        Emit($"        pop {{{reg}}}");
                    }
                    break;

                // 函数调用和返回
                case OpCode.CALL:
                    Emit($"        bl {instr.Operands[0].Value}");
                    break;
                case OpCode.RET:
                    Emit("        bx LR");
                    break;
                // case OpCode.RET_VAL:
                //     Emit($"        movs R0, {GetOperandValue(instr.Operands[0])}");
                //     Emit("        bx LR");
                //     break;

                // 标签定义
                case OpCode.LABEL:
                    Emit($"{instr.Operands[0].Value}:");
                    break;

                // 系统调用 (ALLOC/FREE 通过 SYSCALL 40/41, Cortex-M0: SVC 软中断)
                case OpCode.SYSCALL:
                    Emit($"        svc {GetOperandValue(instr.Operands[0])}");
                    break;

                // 内联汇编
                // OpCode.ASM handled by BaseTranslator.TryTranslateCommonOpcode

                // 栈帧管理
                case OpCode.ENTER:
                    {
                        int size = int.Parse(instr.Operands[0].Value.ToString());
                        Emit($"        push {{r11}}");
                        Emit($"        mov r11, sp");
                        if (size > 0)
                            Emit($"        sub sp, #{size}");
                    }
                    break;
                case OpCode.LEAVE:
                    Emit($"        mov sp, r11");
                    Emit($"        pop {{r11}}");
                    break;

                // 标志位控制 (ARM-M0 标志位自动设置)
                // 地址计算
                                // 调试
                case OpCode.BREAK:
                    Emit($"        bkpt #0");
                    break;

                // 8位数据传输: MOVEB dst, src
                case OpCode.MOVEB:
                    TranslateByteHalfMove(instr, "b");
                    break;
                // 16位数据传输: MOVEH dst, src
                case OpCode.MOVEH:
                    TranslateByteHalfMove(instr, "h");
                    break;
                case OpCode.PUSHB:
                    Emit($"        push {{{GetOperandValue(instr.Operands[0])}}}");
                    break;
                case OpCode.PUSHH:
                    Emit($"        push {{{GetOperandValue(instr.Operands[0])}}}");
                    break;
                case OpCode.POPB:
                    {
                        string reg = GetOperandValue(instr.Operands[0]);
                        Emit($"        pop {{{reg}}}");
                        Emit($"        uxtb {reg}, {reg}");
                    }
                    break;
                case OpCode.POPH:
                    {
                        string reg = GetOperandValue(instr.Operands[0]);
                        Emit($"        pop {{{reg}}}");
                        Emit($"        uxth {reg}, {reg}");
                    }
                    break;

                case OpCode.I2D:
                case OpCode.D2I:
                    Emit($"        bl __{instr.Opcode.ToString().ToLower()}");
                    break;

                // ═══════════════════════════════════════════════════════
                // 64-bit 位运算 (v1.66.28+)
                // ═══════════════════════════════════════════════════════
                case OpCode.ANDL:
                    Translate64BitPairOp(instr, "ands");
                    break;
                case OpCode.ORL:
                    Translate64BitPairOp(instr, "orrs");
                    break;
                case OpCode.XORL:
                    Translate64BitPairOp(instr, "eors");
                    break;
                case OpCode.NOTL:
                    {
                        // NOTL dst, src → ~src (64-bit)
                        int dstReg = (int)instr.Operands[0].Value;
                        int srcReg = (int)instr.Operands[1].Value;
                        Emit($"        @ NOTL R{dstReg}:R{dstReg+1} ← ~R{srcReg}:R{srcReg+1}");
                        Emit($"        mvns R{dstReg}, R{srcReg}");
                        Emit($"        mvns R{dstReg+1}, R{srcReg+1}");
                    }
                    break;

                // ═══════════════════════════════════════════════════════
                // 64-bit 移位 (v1.66.28+) — 软件库调用
                // ═══════════════════════════════════════════════════════
                case OpCode.SHLL:
                case OpCode.SHRL:
                    Emit($"        bl __{instr.Opcode.ToString().ToLower()}");
                    break;

                // ═══════════════════════════════════════════════════════
                // 符号扩展 (v1.66.28+) — ARM 原生支持
                // ═══════════════════════════════════════════════════════
                case OpCode.SEXTB:
                    {
                        int dst = (int)instr.Operands[0].Value;
                        string src = GetOperandValue(instr.Operands[1]);
                        Emit($"        sxtb R{dst}, {src}");
                    }
                    break;
                case OpCode.SEXTH:
                    {
                        int dst = (int)instr.Operands[0].Value;
                        string src = GetOperandValue(instr.Operands[1]);
                        Emit($"        sxth R{dst}, {src}");
                    }
                    break;

                // ═══════════════════════════════════════════════════════
                // 条件移动 (v1.66.28+)
                // ═══════════════════════════════════════════════════════
                case OpCode.CMOVZ:
                    {
                        // if ZF=1, dst = src (ARM local label)
                        string dst = GetOperandValue(instr.Operands[0]);
                        string src = GetOperandValue(instr.Operands[1]);
                        Emit($"        bne 1f");
                        Emit($"        movs {dst}, {src}");
                        Emit($"1:");
                    }
                    break;
                case OpCode.CMOVNZ:
                    {
                        // if ZF=0, dst = src (ARM local label)
                        string dst = GetOperandValue(instr.Operands[0]);
                        string src = GetOperandValue(instr.Operands[1]);
                        Emit($"        beq 1f");
                        Emit($"        movs {dst}, {src}");
                        Emit($"1:");
                    }
                    break;

                // ═══════════════════════════════════════════════════════
                // 循环移位 (v1.66.28+)
                // ═══════════════════════════════════════════════════════
                case OpCode.ROR:
                    {
                        string dst = MapRegister((int)instr.Operands[0].Value);
                        string src = GetOperandValue(instr.Operands[1]);
                        string n = GetOperandValue(instr.Operands[2]);
                        Emit($"        rors {dst}, {src}, {n}");
                    }
                    break;
                case OpCode.ROL:
                    {
                        // ROL n = ROR (32-n)
                        string dst = MapRegister((int)instr.Operands[0].Value);
                        string src = GetOperandValue(instr.Operands[1]);
                        int n = int.Parse(instr.Operands[2].Value.ToString());
                        Emit($"        rors {dst}, {src}, #{32 - n}");
                    }
                    break;

                default:
                    Emit($"        @ UNIMPLEMENTED: {instr.Opcode.ToString()} {string.Join(", ", instr.Operands)}");
                    break;
            }
        }

        private void TranslateLoad(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src = instr.Operands[1];

            string dstReg = GetOperandValue(dst);

            if (src.Type == OperandType.IMMEDIATE)
            {
                string srcStr = src.Value.ToString();
                if (!int.TryParse(srcStr, out int val))
                {
                    // Try float (e.g. "1E-10" = 1×10⁻¹⁰, convert to IEEE 754 bits)
                    if (float.TryParse(srcStr, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out float fval))
                    {
                        val = BitConverter.SingleToInt32Bits(fval);
                    }
                }
                if (val >= 0 && val <= 255)
                {
                    Emit($"        movs {dstReg}, #{val}");
                }
                else
                {
                    // Use ldr =value for large immediates (>8 bits)
                    Emit($"        ldr {dstReg}, ={val}");
                }
            }
            else if (src.Type == OperandType.MEMORY)
            {
                Emit($"        ldr {dstReg}, [{src.Value}]");
            }
            else if (src.Type == OperandType.INDIRECT)
            {
                // Register-indirect load: MOVE Rd, @Rs → ldr Rd, [Rs]
                string srcReg = MapRegister((int)src.Value);
                Emit($"        ldr {dstReg}, [{srcReg}]");
            }
            else if (src.Type == OperandType.REGISTER)
            {
                // Register-to-register move: MOVE Rd, Rs
                string srcReg = GetOperandValue(src);
                Emit($"        movs {dstReg}, {srcReg}");
            }
            else if (src.Type == OperandType.LABEL)
            {
                // Load a label address into register
                Emit($"        ldr {dstReg}, ={src.Value}");
            }
        }

        private void TranslateStore(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src = instr.Operands[1];

            string srcReg = GetOperandValue(src);

            if (dst.Type == OperandType.MEMORY)
            {
                Emit($"        str {srcReg}, [{dst.Value}]");
            }
            else if (dst.Type == OperandType.INDIRECT)
            {
                // Register-indirect store: MOVE @Raddr, Rs → str Rs, [Raddr]
                string dstReg = MapRegister((int)dst.Value);
                Emit($"        str {srcReg}, [{dstReg}, #0]");
            }
        }

        private void TranslateAdd(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            string dstReg = GetOperandValue(dst);
            string src1Reg = GetOperandValue(src1);

            if (src2.Type == OperandType.IMMEDIATE)
            {
                Emit($"        adds {dstReg}, {src1Reg}, #{src2.Value}");
            }
            else
            {
                string src2Reg = GetOperandValue(src2);
                Emit($"        adds {dstReg}, {src1Reg}, {src2Reg}");
            }
        }

        private void TranslateSub(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            string dstReg = GetOperandValue(dst);
            string src1Reg = GetOperandValue(src1);

            if (src2.Type == OperandType.IMMEDIATE)
            {
                Emit($"        subs {dstReg}, {src1Reg}, #{src2.Value}");
            }
            else
            {
                string src2Reg = GetOperandValue(src2);
                Emit($"        subs {dstReg}, {src1Reg}, {src2Reg}");
            }
        }

        private void TranslateMul(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            string dstReg = GetOperandValue(dst);
            string src1Reg = GetOperandValue(src1);

            if (src2.Type == OperandType.IMMEDIATE)
            {
                // Thumb muls doesn't accept immediate — use lsls for power-of-2
                int val = int.Parse(src2.Value.ToString());
                if (val == 2)
                    Emit($"        lsls {dstReg}, {src1Reg}, #1");
                else if (val == 4)
                    Emit($"        lsls {dstReg}, {src1Reg}, #2");
                else if (val == 8)
                    Emit($"        lsls {dstReg}, {src1Reg}, #3");
                else
                {
                    Emit($"        movs R4, #{val}");
                    Emit($"        muls {dstReg}, {src1Reg}, R4");
                }
            }
            else
            {
                string src2Reg = GetOperandValue(src2);
                Emit($"        muls {dstReg}, {src1Reg}, {src2Reg}");
            }
        }

        private void TranslateMove(Instruction instr)
        {
            // v1.65.167+: 统一 MOVE — MEM/LABEL dest → Store, 其他 → Load
            if (instr.Operands[0].Type == OperandType.MEMORY ||
                instr.Operands[0].Type == OperandType.INDIRECT ||
                instr.Operands[0].Type == OperandType.LABEL)
            {
                TranslateStore(instr);
                return;
            }
            TranslateLoad(instr);
        }

        /// <summary>翻译 MOVEB/MOVEH 字节/半字传输指令</summary>
        private void TranslateByteHalfMove(Instruction instr, string suffix)
        {
            // STORE 路径: dst 是 INDIRECT 或 MEMORY
            if (instr.Operands[0].Type == OperandType.INDIRECT)
            {
                string dstRegI = MapRegister((int)instr.Operands[0].Value);
                string srcReg = GetOperandValue(instr.Operands[1]);
                Emit($"        str{suffix} {srcReg}, [{dstRegI}, #0]");
                return;
            }
            if (instr.Operands[0].Type == OperandType.MEMORY)
            {
                string srcReg = GetOperandValue(instr.Operands[1]);
                Emit($"        str{suffix} {srcReg}, [{instr.Operands[0].Value}]");
                return;
            }

            // LOAD 路径: src 是 INDIRECT 或 MEMORY
            string dstReg = GetOperandValue(instr.Operands[0]);
            if (instr.Operands[1].Type == OperandType.INDIRECT)
            {
                string srcReg = MapRegister((int)instr.Operands[1].Value);
                Emit($"        ldr{suffix} {dstReg}, [{srcReg}]");
                return;
            }
            if (instr.Operands[1].Type == OperandType.MEMORY)
            {
                Emit($"        ldr{suffix} {dstReg}, [{instr.Operands[1].Value}]");
                return;
            }

            // REGISTER → REGISTER: zero-extend
            string srcReg2 = GetOperandValue(instr.Operands[1]);
            Emit($"        movs {dstReg}, {srcReg2}");
            Emit($"        uxt{suffix} {dstReg}, {dstReg}");
        }

        private int ParseRegNum(string reg)
        {
            if (reg.StartsWith("R") || reg.StartsWith("r"))
                return int.TryParse(reg.Substring(1), out int n) ? n : 0;
            if (reg == "sp" || reg == "SP") return 13;
            if (reg == "lr" || reg == "LR") return 14;
            if (reg == "pc" || reg == "PC") return 15;
            return 0;
        }

        private void TranslateCmp(Instruction instr)
        {
            var src1 = instr.Operands[0];
            var src2 = instr.Operands[1];

            string src1Reg = GetOperandValue(src1);

            if (src2.Type == OperandType.IMMEDIATE)
            {
                Emit($"        cmp {src1Reg}, #{src2.Value}");
            }
            else
            {
                string src2Reg = GetOperandValue(src2);
                Emit($"        cmp {src1Reg}, {src2Reg}");
            }
        }

        /// <summary>64-bit pairwise operation: dstLo:Hi = src1Lo:Hi OP src2Lo:Hi</summary>
        private void Translate64BitPairOp(Instruction instr, string armOp)
        {
            int dstReg = (int)instr.Operands[0].Value;
            int src1Reg = (int)instr.Operands[1].Value;
            int src2Reg = (int)instr.Operands[2].Value;
            string opName = instr.Opcode.ToString();
            Emit($"        @ {opName} R{dstReg}:R{dstReg+1} ← R{src1Reg}:R{src1Reg+1} {opName[..^1]} R{src2Reg}:R{src2Reg+1}");
            Emit($"        {armOp} R{dstReg}, R{src1Reg}, R{src2Reg}");
            Emit($"        {armOp} R{dstReg+1}, R{src1Reg+1}, R{src2Reg+1}");
        }

        protected override string MapRegister(int regNum)
        {
            return REGISTER_MAP.TryGetValue(regNum, out string reg) ? reg : $"R{regNum}";
        }
    }
}
